import base64
from taf.internal.robot_typecasts import time_to_seconds


class FileCollectionInterface(object):

    def get_scf(self, export_type=None, timeout=120):
        """Get SCF file content

        :param string export_type: configuration, configurationAndRuntimeObjects or runtimeObjects. None means default Admin API behavior.
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: file content
        """
        timeout = time_to_seconds(timeout)
        assert export_type in (None, "configuration", "configurationAndRuntimeObjects", "runtimeObjects")

        parameters = {"exportType": export_type} if export_type else {}
        scf = self._api_client.execute_procedure("generateScf", parameters, timeout)
        return base64.b64decode(scf).decode('utf-8')

    def collect_scf(self, target_file_name, export_type=None, timeout=120):
        """Collect SCF file.

        :param string target_file_name: target SCF filename.
        :param string export_type: configuration, configurationAndRuntimeObjects or runtimeObjects. None means default Admin API behavior.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(target_file_name)
        assert export_type in (None, "configuration", "configurationAndRuntimeObjects", "runtimeObjects")

        parameters = {"exportType": export_type} if export_type else {}
        self._api_client.execute_procedure("generateScf", parameters, timeout, output_file_name=target_file_name)

    def get_raw_alarm_history_file(self, timeout=120):
        """Get raw alarm history file content.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: file content

        :note: Experimental keyword.
        """
        timeout = time_to_seconds(timeout)

        alarm_history = self._api_client.execute_procedure("getRawAlarmHistory", {}, timeout)
        return base64.b64decode(alarm_history).decode('utf-8')

    def collect_raw_alarm_history_file(self, target_file_name, timeout=120):
        """Collect raw alarm history file.

        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        

        :note: Experimental keyword.
        """
        timeout = time_to_seconds(timeout)
        str(target_file_name)

        self._api_client.execute_procedure("getRawAlarmHistory", {}, timeout, output_file_name=target_file_name)

    def get_frequency_history_file(self, dist_name, timeout=120):
        """Get frequency history file content.

        :param string dist_name: SMOD or CLOCK dist name.
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: file content
        """
        timeout = time_to_seconds(timeout)
        str(dist_name)

        alarm_history = self._api_client.execute_procedure("getFrequencyHistory", {"targetDN": dist_name}, timeout)
        return base64.b64decode(alarm_history).decode('utf-8')

    def collect_frequency_history_file(self, dist_name, target_file_name, timeout=120):
        """Collect frequency history file.

        :param string dist_name: SMOD or CLOCK dist name.
        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(dist_name)
        str(target_file_name)

        self._api_client.execute_procedure("getFrequencyHistory", {"targetDN": dist_name}, timeout, output_file_name=target_file_name)

    def collect_pm_files(self, target_file_name, timeout=120):
        """Collect PM files.

        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(target_file_name)

        self._api_client.execute_infomodel_request("getPmFiles", {}, timeout, output_file_name=target_file_name)
